input.sparql:
SELECT ?point ?ts WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_bot_ZN_1" .
  ?point brick:isPartOf ?z ; a brick:AirTemperature .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
}

SELECT ?point ?ts WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_1" .
  ?z brick:hasPoint ?point .
  ?point brick:isPointOf ?z .
  FILTER(?s = ?point)
}

SELECT ?point ?ref ?ts WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_1" .
  ?z brick:hasPoint ?point .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT ?unit WHERE {
  ?p rdfs:label "Perimeter_bot_ZN_1 Zone Air Temperature Sensor" .
}
